// Choose the two highest-valued elements among indices i, j, k.
// Returns (a, b) such that valores[a] >= valores[b] and {a, b} ⊆ {i, j, k}.
pub fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    let mut idx = [i, j, k];

    // Sort indices by their corresponding values descending.
    // Any ordering among ties is acceptable per statement.
    idx.sort_by(|&a, &b| valores[b].cmp(&valores[a]));

    (idx[0], idx[1])
}